<?php
require '../config/db.php';require '../config/auth.php';require_role('admin','login.php');$u=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';$id=(int)($_POST['id']??0);if($a==='save'){$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');$cap=max(1,(int)($_POST['capacity']??1));if($name==='')flash('error','Resource name is required.');elseif($id){$pdo->prepare('UPDATE resources SET name=?,description=?,capacity=? WHERE id=?')->execute([$name,$desc,$cap,$id]);log_activity($pdo,$u['id'],'Updated resource',$name);flash('success','Resource updated.');}else{$pdo->prepare('INSERT INTO resources(name,description,capacity) VALUES(?,?,?)')->execute([$name,$desc,$cap]);log_activity($pdo,$u['id'],'Added resource',$name);flash('success','Resource added.');}}elseif($a==='toggle'&&$id){$pdo->prepare("UPDATE resources SET status=IF(status='available','unavailable','available') WHERE id=?")->execute([$id]);}elseif($a==='delete'&&$id){$s=$pdo->prepare('SELECT COUNT(*) FROM appointments WHERE resource_id=?');$s->execute([$id]);if($s->fetchColumn())flash('error','This resource has booking history and cannot be deleted. Set it unavailable instead.');else{$pdo->prepare('DELETE FROM resources WHERE id=?')->execute([$id]);flash('success','Resource deleted.');}}redirect('resources.php');}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM resources WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$rows=$pdo->query("SELECT r.*,(SELECT COUNT(*) FROM appointments a WHERE a.resource_id=r.id AND a.appointment_date=CURDATE() AND a.status='approved') today_count,(SELECT COUNT(*) FROM appointments a WHERE a.resource_id=r.id) total_count FROM resources r ORDER BY r.name")->fetchAll();
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Resources</title><link rel="stylesheet" href="../assets/css/style.css?v=resources-modal-20261002"><style>
#resourceModal.resource-modal{position:fixed!important;inset:0!important;z-index:5000!important;display:none!important;align-items:center!important;justify-content:center!important;padding:24px!important;background:rgba(18,24,33,.52)!important;backdrop-filter:blur(4px)}
