#resourceModal .resource-modal-dialog{position:relative!important;width:min(680px,calc(100vw - 32px))!important;max-height:calc(100dvh - 48px)!important;overflow:auto!important;background:#fffdf9!important;border:1px solid #e5dccf!important;border-radius:22px!important;padding:26px!important;box-shadow:0 28px 80px rgba(17,24,39,.25)!important}
#resourceModal .resource-modal-head{display:flex!important;align-items:flex-start!important;justify-content:space-between!important;gap:18px!important;margin-bottom:18px!important}
