</style></head><body><div class="shell"><?php include 'includes/sidebar.php'?><main class="main"><header class="topbar"><div><button class="btn light mobile-toggle" data-nav-toggle>☰</button><div class="eyebrow">Facilities</div><h1>Resources.</h1></div><div class="topbar-actions"><button type="button" class="btn" id="openResourceModal">+ Add Resource</button></div></header><?php if($m=flash('success')):?><div class="notice"><?=e($m)?></div><?php endif;if($m=flash('error')):?><div class="notice error"><?=e($m)?></div><?php endif;?><section data-live-scope><div class="live-filter-bar"><label class="field live-search-field">Search resources<input class="search" type="search" data-live-search placeholder="Start typing to filter..."></label><button type="button" class="btn light" data-live-clear>Clear</button><span class="live-filter-meta" data-live-count></span></div><div class="grid three" data-live-list><div class="card live-empty" data-live-empty hidden>No resources match your search.</div><?php foreach($rows as $r):?><article class="card" data-live-item data-search="<?=e(strtolower($r['name'].' '.($r['description']??'').' '.$r['status']))?>"><div class="eyebrow"><?=e($r['status'])?></div><h2><?=e($r['name'])?></h2><p class="muted"><?=e($r['description'])?></p><p>Capacity <b><?=$r['capacity']?></b> · Today <b><?=$r['today_count']?></b> · Total <b><?=$r['total_count']?></b></p><div class="actions"><button type="button" class="btn light small resource-edit-btn" data-id="<?=$r['id']?>" data-name="<?=e($r['name'])?>" data-capacity="<?=$r['capacity']?>" data-description="<?=e($r['description'])?>">Edit</button><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn light small">Toggle</button></form><form method="post" onsubmit="return confirm('Delete this resource?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger small">Delete</button></form></div></article><?php endforeach?></div></section>
<div class="resource-modal" id="resourceModal" aria-hidden="true"><div class="resource-modal-dialog" role="dialog" aria-modal="true" aria-labelledby="resourceModalTitle"><div class="resource-modal-head"><div><div class="eyebrow" id="resourceModalEyebrow">New resource</div><h2 id="resourceModalTitle">Add resource</h2><p class="muted" id="resourceModalHelp">Add a facility or room that can be assigned to bookings.</p></div><button type="button" class="resource-modal-close" id="closeResourceModal" aria-label="Close">×</button></div>
<form method="post" class="form-grid" id="resourceForm"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" id="resourceId" value="0"><label class="field">Name<input name="name" id="resourceName" required placeholder="e.g. Parish Hall"></label><label class="field">Capacity<input type="number" name="capacity" id="resourceCapacity" min="1" required value="1"></label><label class="field full">Description<textarea name="description" id="resourceDescription" rows="4" placeholder="Briefly describe this resource."></textarea></label><div class="modal-actions full"><button class="btn light" type="button" id="cancelResourceModal">Cancel</button><button class="btn" id="resourceSubmit">Add resource</button></div></form></div></div>
<script>
(()=>{const modal=document.getElementById('resourceModal'),form=document.getElementById('resourceForm'),id=document.getElementById('resourceId'),name=document.getElementById('resourceName'),capacity=document.getElementById('resourceCapacity'),description=document.getElementById('resourceDescription'),title=document.getElementById('resourceModalTitle'),eyebrow=document.getElementById('resourceModalEyebrow'),help=document.getElementById('resourceModalHelp'),submit=document.getElementById('resourceSubmit');
function show(edit){if(edit){id.value=edit.dataset.id;name.value=edit.dataset.name||'';capacity.value=edit.dataset.capacity||1;description.value=edit.dataset.description||'';eyebrow.textContent='Editing resource';title.textContent='Edit resource';help.textContent='Update this resource without leaving the resource list.';submit.textContent='Save changes'}else{form.reset();id.value='0';capacity.value='1';eyebrow.textContent='New resource';title.textContent='Add resource';help.textContent='Add a facility or room that can be assigned to bookings.';submit.textContent='Add resource'}modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.body.classList.add('modal-open');setTimeout(()=>name.focus(),50)}
function hide(){modal.classList.remove('open');modal.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open')}
document.getElementById('openResourceModal').addEventListener('click',()=>show());document.querySelectorAll('.resource-edit-btn').forEach(b=>b.addEventListener('click',()=>show(b)));document.getElementById('closeResourceModal').addEventListener('click',hide);document.getElementById('cancelResourceModal').addEventListener('click',hide);modal.addEventListener('click',e=>{if(e.target===modal)hide()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal.classList.contains('open'))hide()});
<?php if($edit): ?>show(document.querySelector('.resource-edit-btn[data-id="<?=$edit['id']?>"]'));<?php endif; ?>
})();
</script></main></div><script src="../assets/js/script.js"></script></body></html>
